SELECT t.id, t.tranid, BUILTIN.DF(t.entity) AS customer, TO_CHAR(t.duedate, 'YYYY-MM-DD') AS duedate, t.foreigntotal AS total, t.foreignamountpaid AS paid, t.foreignamountunpaid AS remaining, BUILTIN.DF(t.status) AS status, BUILTIN.DF(t.currency) AS currency, BUILTIN.DF(t.subsidiary) AS subsidiary FROM transaction t WHERE t.type = 'CustInvc' AND t.foreignamountunpaid > 0 AND t.duedate IS NOT NULL AND t.duedate <= TRUNC(SYSDATE) - :min_days AND (:customer_id IS NULL OR t.entity = :customer_id) ORDER BY t.duedate, t.id
